#!/usr/bin/env node
// The TypeScript SDK's API report (docs/release-management.md, "Supply chain
// and policies"): the public declarations of a project, committed as
// <project>/etc/api-report.d.ts, so that the `changes` check can tell a
// breaking change from an addition. Paths are relative to the working
// directory (the repository root; the tests run it in fixture repositories).
// Rules:
//
// R1 The report is generated by the repository's own tsc:
//    `tsc -p <project>/tsconfig.json --declaration --emitDeclarationOnly
//    --noEmit false --removeComments --rootDir <project> --outDir <tmp>`
//    (rootDir fixes the output layout, so src/ is always <tmp>/src/). A tsc
//    error fails the run with tsc's output; a tsc that cannot start or runs
//    longer than five minutes (API_REPORT_TSC_TIMEOUT_MS overrides that,
//    for the tests) or prints more than TSC_MAX_BUFFER fails it with the
//    cause. Comments are removed, so a doc comment edit is never reported
//    as an API change. A value of --base or --project that starts with a
//    dash is a usage error.
// R2 The report is every <tmp>/src/**/*.d.ts in sorted path order, each
//    preceded by `// file: <path relative to src/>`, normalised to LF. The
//    project's tests (anything outside src/) are not part of it.
// R3 Check mode (default): the regenerated report must equal the committed
//    one; a missing or differing report fails, naming the file and the
//    command that rewrites it. --write writes it instead.
// R4 --base <rev>: after R3 holds, the report at <rev> (absent there: empty)
//    is compared line by line with the regenerated one. Every line of the
//    base that the new report no longer has (a removed or changed
//    declaration) is printed as `api-report: breaking: - <line>` and the run
//    exits 3. Blank lines, `export {};` and lines of closing brackets only
//    carry no API of their own and are never reported. Additions pass.
//
// Exit 0 when the rules hold, 1 on a stale report, a tsc or git error, 2 on
// a usage error, 3 when --base found a breaking change.
import { spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { cli } from "./lib/cli.mjs";
import { git } from "./lib/git.mjs";

const USAGE = `usage: api-report [--write | --base <rev>] [--project <dir>]
Regenerates the public declarations of <dir> (default packages/sdk) with tsc
and compares them with the committed <dir>/etc/api-report.d.ts; fails when it
is out of date. --write rewrites it. --base <rev> also compares it with the
report at <rev> and exits 3, naming each line, when a line was removed or
changed (a breaking change); additions pass.`;

const { fail, usageError, parseArgs } = cli("api-report", USAGE);

const BREAKING = 3;
const REWRITE = "node scripts/release/api-report.mjs --write";

/** The repository's tsc: the typescript devDependency of the root package. */
const tscPath = () => {
  const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
  const require = createRequire(join(root, "package.json"));
  const manifest = require.resolve("typescript/package.json");
  const { bin } = JSON.parse(readFileSync(manifest, "utf8"));
  return join(dirname(manifest), typeof bin === "string" ? bin : bin.tsc);
};

/** Every *.d.ts below `dir`, as paths relative to it with `/`, sorted. */
const declarations = (dir) =>
  existsSync(dir)
    ? readdirSync(dir, { recursive: true, withFileTypes: true })
        .filter((entry) => entry.isFile() && entry.name.endsWith(".d.ts"))
        .map((entry) =>
          relative(dir, join(entry.parentPath, entry.name))
            .split(sep)
            .join("/"),
        )
        .sort()
    : [];

const lf = (text) => text.replace(/\r\n?/g, "\n");

/** tsc's time limit; API_REPORT_TSC_TIMEOUT_MS is a test seam. */
const TSC_TIMEOUT_MS = Number(process.env.API_REPORT_TSC_TIMEOUT_MS) || 300_000;

/** tsc's output limit, far above what a declaration emit prints. */
const TSC_MAX_BUFFER = 64 * 1024 * 1024;

/** A failure `main` reports once, after what is already on stderr. */
class Failure extends Error {}

/** R1, R2: the report as a string; throws a Failure when tsc fails. */
function generate(project) {
  const out = mkdtempSync(join(tmpdir(), "api-report-"));
  try {
    const result = spawnSync(
      process.execPath,
      [
        tscPath(),
        "-p",
        join(project, "tsconfig.json"),
        "--declaration",
        "--emitDeclarationOnly",
        "--noEmit",
        "false",
        "--removeComments",
        "--rootDir",
        project,
        "--outDir",
        out,
      ],
      {
        encoding: "utf8",
        maxBuffer: TSC_MAX_BUFFER,
        timeout: TSC_TIMEOUT_MS,
      },
    );
    const config = join(project, "tsconfig.json");
    if (result.error)
      throw new Failure(
        `tsc did not run to the end on ${config}: ${result.error.message}`,
      );
    if (result.status !== 0) {
      process.stderr.write(result.stdout ?? "");
      process.stderr.write(result.stderr ?? "");
      throw new Failure(
        `tsc failed on ${config} (exit ${result.status ?? result.signal})`,
      );
    }
    const src = join(out, "src");
    return declarations(src)
      .map((file) => {
        const body = lf(readFileSync(join(src, file), "utf8")).replace(
          /\n*$/,
          "\n",
        );
        return `// file: ${file}\n${body}`;
      })
      .join("");
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
}

/** Lines that carry no API of their own (R4). */
const STRUCTURAL = /^\s*(?:export \{\};|[}\])]+[;,]?)?\s*$/;

/** R4: the base's lines the new report no longer has, as a multiset. */
export function removedLines(before, after) {
  const left = new Map();
  for (const line of after.split("\n"))
    left.set(line, (left.get(line) ?? 0) + 1);
  const removed = [];
  for (const line of before.split("\n")) {
    const count = left.get(line) ?? 0;
    if (count > 0) left.set(line, count - 1);
    else if (!STRUCTURAL.test(line)) removed.push(line);
  }
  return removed;
}

/** The committed report at `rev`, "" when it is absent there. */
const reportAt = (rev, path) => {
  git(["rev-parse", "--verify", "--quiet", `${rev}^{commit}`]);
  const spec = `${rev}:./${path}`;
  try {
    git(["cat-file", "-e", spec]);
  } catch {
    return "";
  }
  return lf(git(["show", spec]));
};

function main(args) {
  const opts = parseArgs(args, {
    flags: ["--write"],
    values: ["--base", "--project"],
    defaults: { project: "packages/sdk" },
  });
  if (opts.write && opts.base) usageError();
  // A value that starts with a dash would reach git or tsc as an option.
  if ([opts.base, opts.project].some((value) => value?.startsWith("-")))
    usageError();
  const path = join(opts.project, "etc", "api-report.d.ts")
    .split(sep)
    .join("/");

  let report;
  try {
    report = generate(opts.project);
  } catch (error) {
    if (!(error instanceof Failure)) throw error;
    fail(error.message);
    return;
  }

  if (opts.write) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, report);
    console.log(`api-report: wrote ${path}`);
    return;
  }

  const committed = existsSync(path) ? lf(readFileSync(path, "utf8")) : null;
  if (committed !== report) {
    fail(`${path} is out of date; run ${REWRITE}`);
    return;
  }
  if (!opts.base) {
    console.log(`api-report: ${path} is up to date`);
    return;
  }

  let before;
  try {
    before = reportAt(opts.base, path);
  } catch (error) {
    fail(`cannot read the report at ${opts.base}: ${error.message}`);
    return;
  }
  const removed = removedLines(before, report);
  for (const line of removed) console.log(`api-report: breaking: - ${line}`);
  if (removed.length > 0) {
    process.exitCode = BREAKING;
    return;
  }
  console.log(`api-report: no line removed or changed since ${opts.base}`);
}

if (
  process.argv[1] &&
  realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))
) {
  main(process.argv.slice(2));
}
